SELECT count(*)::text AS video_count, statement_timestamp() AS calculated_at FROM strategies AS s CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(s.media_files)='array' THEN s.media_files ELSE '[]'::jsonb END) AS m(value) WHERE s.status='published' AND jsonb_typeof(m.value)='object' AND m.value->>'type'='video' AND jsonb_typeof(m.value->'url')='string' AND (m.value->>'url' IS NOT NULL AND octet_length(m.value->>'url') BETWEEN 1 AND 2048 AND m.value->>'url' ~* '^(?:https?://(?:(?=[^/?#:]*[a-z])[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)*|(?:25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9]?[0-9])(?:\.(?:25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9]?[0-9])){3})(?::(?:[1-9][0-9]{0,3}|[1-5][0-9]{4}|6[0-4][0-9]{3}|65[0-4][0-9]{2}|655[0-2][0-9]|6553[0-5]))?(?:[/?#][^\s\\<>"`\x01-\x1f\x7f]*)?|/(?!/)[^\s\\<>"`\x01-\x1f\x7f]*)$' AND m.value->>'url' !~ '[   -     　﻿]' AND m.value->>'url' !~* '%(?![a-f0-9]{2})' AND strpos(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(regexp_replace(split_part(split_part(lower(m.value->>'url'),'?',1),'#',1),'^https?://[^/]*',''),'%2e','.'),'%2f','/'),'%5c','\'),'%31','1'),'%32','2'),'%6d','m'),'%4d','m'),'%70','p'),'%50','p'),'%34','4'),'\')=0 AND replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(regexp_replace(split_part(split_part(lower(m.value->>'url'),'?',1),'#',1),'^https?://[^/]*',''),'%2e','.'),'%2f','/'),'%5c','\'),'%31','1'),'%32','2'),'%6d','m'),'%4d','m'),'%70','p'),'%50','p'),'%34','4') !~ '(^|/)[.]{1,2}(/|$)' AND NOT ((m.value->>'url' LIKE '/%' OR m.value->>'url' ~* '^https?://jinxi-web[.]netlify[.]app(?::(?:80|443))?(?:[/?#]|$)') AND replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(regexp_replace(split_part(split_part(lower(m.value->>'url'),'?',1),'#',1),'^https?://[^/]*',''),'%2e','.'),'%2f','/'),'%5c','\'),'%31','1'),'%32','2'),'%6d','m'),'%4d','m'),'%70','p'),'%50','p'),'%34','4') ~ '^/[12][.]mp4$'));
